int main(void) {
    int a[] = {5, 1, 4, 2, 3}, n = 5;
    for (int pass = 0; pass < n - 1; pass++) {
        for (int j = 0; j < n - 1 - pass; j++) {
            if (a[j] > a[j + 1]) {
                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
            }
        }
    }
    for (int i = 0; i < n; i++) printf("%s%d", i ? " " : "", a[i]);
    printf("\n");
    return 0;
}

