#include <stdio.h>
#include <string.h>

int main(void) {
    char text[32];
    if (!fgets(text, sizeof text, stdin)) return 1;
    text[strcspn(text, "\n")] = '\0';
    size_t len = strlen(text);
    int palindrome = 1;
    for (size_t i = 0; i < len / 2; i++) {
        if (text[i] != text[len - 1 - i]) { palindrome = 0; break; }
    }
    printf("%zu %s\n", len, palindrome ? "yes" : "no");
    return 0;
}

