int main(void) {
    FILE *f = fopen("study_scores.txt", "w+");
    if (!f) return 1;
    if (fprintf(f, "73 90 80\n") < 0) { fclose(f); return 1; }
    rewind(f);
    int x, sum = 0, count = 0, result;
    while ((result = fscanf(f, "%d", &x)) == 1) { sum += x; count++; }
    if (ferror(f) || result != EOF) { fclose(f); return 1; }
    if (count > 0) printf("%.1f\n", (double)sum / count);
    rewind(f);
    if (fscanf(f, "%d", &x) == 1) printf("%d\n", x);
    return fclose(f) == 0 ? 0 : 1;
}

