#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

static int parse_port(const char *s, int *out) {
    if (!s[0]) return 0;
    for (const char *p = s; *p; ++p)
        if (*p < '0' || *p > '9') return 0;
    errno = 0;
    char *end;
    long value = strtol(s, &end, 10);
    if (errno == ERANGE || *end || value < 1 || value > 65535) return 0;
    *out = (int)value;
    return 1;
}

int main(void) {
    int p = 0;
    printf("%d\n", parse_port("8080abc", &p));
    if (parse_port("8080", &p)) printf("%d\n", p);
    return 0;
}

