#ifdef _WIN32
    WSADATA ws;
    if (WSAStartup(MAKEWORD(2, 2), &ws) != 0) return 1;
#endif
    int result = 1;
    socket_t server = BAD, client = BAD, peer = BAD;
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof addr);
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(0);
    server = socket(AF_INET, SOCK_STREAM, 0);
    if (server == BAD || bind(server, (struct sockaddr *)&addr, sizeof addr) != 0 || listen(server, 1) != 0) goto done;
    addr_size size = sizeof addr;
    if (getsockname(server, (struct sockaddr *)&addr, &size) != 0) goto done;
    client = socket(AF_INET, SOCK_STREAM, 0);
    if (client == BAD || connect(client, (struct sockaddr *)&addr, sizeof addr) != 0) goto done;
    peer = accept(server, NULL, NULL);
    if (peer == BAD) goto done;
    const char text[] = "hello";
    size_t sent = 0, received = 0, total = sizeof text - 1;
    char buffer[16] = {0};
    while (sent < total) {
        int n = (int)send(client, text + sent, (int)(total - sent), 0);
        if (n <= 0) goto done;
        sent += (size_t)n;
    }
    while (received < total) {
        int n = (int)recv(peer, buffer + received, (int)(total - received), 0);
        if (n <= 0) goto done;
        received += (size_t)n;
    }
    puts(buffer);
    result = 0;
done:
    if (peer != BAD) shut_socket(peer);
    if (client != BAD) shut_socket(client);
    if (server != BAD) shut_socket(server);
#ifdef _WIN32
    WSACleanup();
#endif
    return result;
}

