#include <stdio.h>
#include <string.h>
#include <stdint.h>

static int summarize(FILE *f, size_t *ok, size_t *error) {
    char line[64];
    *ok = 0; *error = 0;
    while (fgets(line, sizeof line, f)) {
        size_t n = strlen(line);
        if (n && line[n - 1] == '\n') line[--n] = '\0';
        else if (!feof(f)) return 0;
        if (n && line[n - 1] == '\r') line[--n] = '\0';
        if (strcmp(line, "OK") == 0) { if (*ok == SIZE_MAX) return 0; ++*ok; }
        else if (strcmp(line, "ERROR") == 0) { if (*error == SIZE_MAX) return 0; ++*error; }
        else return 0;
    }
    return !ferror(f);
}

int main(void) {
    FILE *f = tmpfile();
    if (!f) return 1;
    if (fputs("OK\nERROR\nOK\n", f) == EOF) { fclose(f); return 1; }
    rewind(f);
    size_t ok = 0, error = 0;
    int good = summarize(f, &ok, &error);
    if (fclose(f) != 0) good = 0;
    if (!good) return 1;
    printf("OK=%zu ERROR=%zu\n", ok, error);
    return 0;
}

